from pathlib import Path
import json
H=Path(__file__).resolve().parent; R=H.parents[3]; P=H.parent/'2026-09-19-review-comparison'; prefix=H.relative_to(R).as_posix(); M='QFEP_Edge_Of_Chaos'
def para(start,old=False):
 p=(H/'before' if old else R)/'commons/maps'/M/'final.md'
 return next(t for t in p.read_text(encoding='utf-8').split('\n\n') if t.startswith(start))
d=json.loads((P/'qfeplaboratory.json').read_text(encoding='utf-8'))
old=json.loads((H/'before/doc/book/iterations/2026-09-19-review-comparison/qfeplaboratory.json').read_text(encoding='utf-8'))
assert d['items'][:len(old['items'])]==old['items'], 'Earlier review cards must remain intact'
d['status']='Introduction, F, E, Lambda, Phi and Edge of Chaos reviewed; Sandbox restoration next'
d['summary']='QFEP asks who may revise the terms. The laboratory moves from different arrangements with a similar total, through prediction, possible branches, recommendations and signed change, to the way a pattern is calculated. Edge of Chaos now offers a real paired experiment: the same starting concentrations and model time, with two numerical step sizes. Six halls have received this pass. Sandbox still needs restoration before its promised control relationships can be examined.'
cards=[
 dict(title='Edge of Chaos: the experiment becomes an encounter',description='Two fields start with identical concentrations and advance to the same model time. The right field takes twice as many smaller steps. The visitor can hold the images, follow one boundary, and repeat the comparison at a finer resolution. The chapter keeps its investigative question and its attention to local features.',images=[prefix+'/edge-dt-coarse.png',prefix+'/edge-dt-finer.png'],captions=['Seed 0, lambda 0.40, model time 60: dt 0.300 / 0.150.','The same seed and duration: dt 0.150 / 0.075.'],image_note='Actual Godot museum images from the same camera. RMS B-field difference falls from 0.00034591 to 0.00017074 in this selected refinement. The images should look close: resolution comparison is not forced visual spectacle. This is evidence for this run, not a universal convergence or criticality result.',text_kind='book — a proposed experiment is now available',before=para('As the next development',True),after=para('There are two images')+'\n\n'+para('Repeat the comparison'),report=prefix+'/final.diff',report_label='Exact Edge manuscript diff'),
 dict(title='Repeat a start, or choose another',description='The former RESEED button always reproduced the same fixed seed. RESTART now names that operation accurately; NEW SEED actually changes the starting concentrations. DT restarts at another numerical resolution, while SIM SPEED changes the requested rate of model time. All controls fit two nearby rows.',images=[prefix+'/edge-controls.png',prefix+'/edge-new-seed.png'],captions=['Full-size sliders and four buttons, checked through their real callbacks.','Seed 1 at the same lambda and model time: a different starting field leaves a different shape.'],image_note='32 runtime interaction/state checks, seven selected walking routes and 16 numerical checks pass. All five tenure variants build. Under load the bounded calculation can lag behind requested speed; the display reports integrated time. Tracked-hand comfort and Quest performance remain unverified.',text_kind='book — keep the action specific',before=para('Initial conditions matter',True),after=para('Initial conditions matter'),report=prefix+'/QFEP_Edge_Of_Chaos-runtime.json',report_label='Controls, state and walking evidence'),
 dict(title='The image and the way it is made',description='Every tenure of the main artifact now uses the same normalized spatial operator and smaller numerical step; the earlier interactive version could be dominated by overshoot and clipping. A separate retained Turing-pattern screen had a malformed shader. It renders again, using noise and trigonometry rather than evolving concentrations. The east-side route is level and the central structure remains.',images=[prefix+'/edge-secondary-pattern.png',prefix+'/edge-gallery.png'],captions=['The repaired secondary pattern screen beside the retained edge core.','The paired experiment faces into its side bay, with a tested route onward.'],image_note='Six map placement families retained; five authored works instantiate. The legacy tt entry has no living scene, and the separate exit teleporter is suppressed by continuous-museum rules. 79 content and preservation checks pass. Six rendered images inspected; final Godot exits 0 with no script or shader compilation errors. Earlier laboratory chapters remain unchanged.',text_kind='book — keep the image open to investigation',before=para('The present numerical update',True),after=para('The earlier calculation'),report=prefix+'/SUMMARY.md',report_label='Decisions, numerical change and limits')]
titles={c['title'] for c in cards}
d['items']=[i for i in d['items'] if i['title'] not in titles]+cards
(P/'qfeplaboratory.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Published three Edge cards; earlier cards preserved')
